// Decided to star exploring built-in functions.
// Needed to lear what is normalization and why it is important.
// Needed to learn about aspect ratio to avoid shape stretching in x or y axis.
// Neened to learn what are UV coordinates, basically X and Y so far.

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // Normalized pixel coordinate (from 0 to 1)
    vec2 uv = fragCoord / iResolution.xy;

    // Aspect ratio correction for landscape and portrait hopefully
    float ar = iResolution.x / iResolution.y; // Width-to-height ratio.
    uv.x *= ar;                               // Scale x-coordinate to match aspect ratio.
    uv -= 0.5 * vec2(ar, 1.0);                // Center the coordinates in the middle.

    // Center of the circle at origin
    float radius = 0.5;                       // Radius of the circle which is 50% of the UV height.
    float dist = length(uv);                  // Distance of the frag from the center.

    // Draw the circle
    float circle = step(dist, radius);        // Inside the circle = 1.0, outside = 0.0.

    // Output to screen (white circle on black background)
    fragColor = vec4(vec3(step(dist,radius)), 1.0);
}

// Remember: this code executes for every single pixel on the screen subspace.
// Or the so-called canvas, vieport, fragCoord space, UV map, etc. ;)
